    71→		}
    72→
    73→		// Reset offset when filter changes
    74→		params.delete('offset');
    75→
    76→		const newUrl = `${base}/tasks?${params.toString()}`;
    77→		goto(newUrl, { replaceState: false, keepFocus: true });
